SELECT , u.nickname AS author_nick, u.portrait AS author_img, t.tag_id, t.tag_name FROM a_article a LEFT JOIN user u ON a.author = u.user_id LEFT JOIN article_to_tag att ON a.article_id = att.article_id LEFT JOIN a_tag t ON att.tag_id = t.tag_id
AND t.tag_id = #{tagId}
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY a.stick DESC, a.published_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(DISTINCT a.article_id) FROM a_article a LEFT JOIN article_to_tag att ON a.article_id = att.article_id LEFT JOIN a_tag t ON att.tag_id = t.tag_id
AND t.tag_id = #{tagId}
AND a.title LIKE CONCAT('%', #{keyword}, '%')

