UPDATE a_article
title = #{title}, content = #{content},
WHERE article_id = #{articleId}

UPDATE a_article
SET page_view = page_view + 1
WHERE article_id = #{articleId}

UPDATE a_article


        SET star = star + #{increment}


        SET `collection` = `collection` + #{increment}


        SET comment = comment + #{increment}


        SET share = share + #{increment}


WHERE article_id = #{articleId}
